import type * as React from "react";

import { cn } from "@/lib/utils";
import { Header } from "./components/header";
import { Sidebar } from "./components/sidebar";

interface PageLayoutProps {
  children: React.ReactNode;
  sidebar?: React.ReactNode;
  header?: React.ReactNode;
  className?: string;
}

function PageLayout({ children, sidebar, header, className }: PageLayoutProps) {
  return (
    <div className={cn("flex min-h-svh", className)}>
      {sidebar ?? <Sidebar />}
      <div className="flex flex-1 flex-col">
        {header ?? <Header />}
        <main className="flex-1 p-6">{children}</main>
      </div>
    </div>
  );
}

export { PageLayout };
export type { PageLayoutProps };

import type * as React from "react";

import { cn } from "@/lib/utils";

interface HeaderProps extends React.ComponentProps<"header"> {
  left?: React.ReactNode;
  right?: React.ReactNode;
}

function Header({ className, left, right, children, ...props }: HeaderProps) {
  return (
    <header
      data-slot="header"
      className={cn(
        "flex h-14 items-center gap-4 border-b bg-background px-6",
        className
      )}
      {...props}
    >
      {left && <div className="flex items-center gap-2">{left}</div>}
      <div className="flex-1">{children}</div>
      {right && (
        <div className="flex items-center gap-2">{right}</div>
      )}
    </header>
  );
}

export { Header };
export type { HeaderProps };

import type * as React from "react";

import { cn } from "@/lib/utils";

interface SidebarProps extends React.ComponentProps<"aside"> {
  collapsed?: boolean;
}

function Sidebar({
  className,
  collapsed = false,
  children,
  ...props
}: SidebarProps) {
  return (
    <aside
      data-slot="sidebar"
      className={cn(
        "flex flex-col border-r bg-sidebar text-sidebar-foreground transition-[width] duration-200",
        collapsed ? "w-16" : "w-64",
        className
      )}
      {...props}
    >
      {children}
    </aside>
  );
}

export { Sidebar };
export type { SidebarProps };
